WITH paid AS MATERIALIZED (SELECT o.order_id,date_trunc('month',o.ordered_at AT TIME ZONE 'UTC')::DATE AS mon FROM orders o WHERE o.status = 'paid' AND o.ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND o.ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00'),order_revenue AS (SELECT p.order_id,p.mon,coalesce(sum(i.qty::DECIMAL(18,0)*i.unit_price)::DECIMAL(38,2),0)::DECIMAL(38,2) AS revenue FROM paid p LEFT JOIN order_items i USING(order_id) GROUP BY p.order_id,p.mon) SELECT mon,avg(revenue)::DECIMAL(38,2) AS revenue FROM order_revenue GROUP BY mon ORDER BY mon;
